python3 - <<EOF
import email
from email import policy
m=email.message_from_file(open("documents/stakeholder-email-thread.eml"),policy=policy.default)
for k,v in m.items(): print(k,":",v)
for p in m.walk():
    if p.get_content_maintype()=="multipart": continue
    print("----",p.get_content_type(),p.get_filename())
    try: print(p.get_content())
    except Exception as e: print(e)
EOF
